import{z as i,x as B,o as t,c as A,q as E,j as o,D as r,d as n,s,S as p,b as a}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"per-tensor / channel / group","description":"","frontmatter":{"title":"per-tensor / channel / group","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/quant-granularity.md","filePath":"llm/quant-granularity.md","lastUpdated":1791413859000}'),g={name:"llm/quant-granularity.md"};function u(d,e,m,h,c,D){const l=B("Mermaid");return t(),A("div",null,[e[2]||(e[2]=E('<h1 id="per-tensor-channel-group" tabindex="-1">per-tensor / channel / group <a class="header-anchor" href="#per-tensor-channel-group" aria-label="Permalink to &quot;per-tensor / channel / group&quot;">​</a></h1><div class="epigraph"><p>尺度共享的范围越大，元数据越少、核越简单、离群越能绑架整张量。粒度是在「一个 $s$ 管多少个数」上买精度。</p><footer>—— 对照 per-tensor INT8 与 GPTQ / AWQ 的分组尺度</footer></div><p><a href="/llm/symmetric-asymmetric-quant">上一课</a> 决定格子滑不滑动。本课决定 <strong>同一套 \\((s,z)\\) 覆盖多大一块</strong>。缺口是粒度：per-tensor、per-channel（通常沿输出通道）、per-group（沿输入通道每 \\(g\\) 个）。<a href="/llm/gptq">GPTQ</a> 常用 \\(g=128\\) 一类分组；AWQ 保护通道也是通道维上的尺度。不要重讲 Hessian，只补共享范围如何与<a href="/llm/why-activation-outliers">离群</a> 相互作用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Per-tensor：一层一个 \\(s\\)。核最简单，离群一个数就拉开整层格子，其余权重挤在零附近。Per-channel：每个输出通道一个 \\(s\\)，匹配「某行权重很大」的结构，INT8 通道尺度是成熟路径。Per-group：把一行再切成组，组内共享 \\(s\\)，逼近逐元素尺度，元数据按 \\(1/g\\) 增长，核要按组反量化。</p><p>\\(g\\) 太小：每参数比特被 scale 吃掉，带宽红利消失。\\(g\\) 太大：组内仍可能有离群。问题是 <strong>误差与元数据与核实现三方同时可行的 \\(g\\)</strong>，不是越小越先进。</p><p><span class="marginnote">数字实例：\\(g=128\\)、每参数 4 bit 时，每 128 个 4-bit 数才摊一个 16-bit scale，折合约 0.125 bit 的元数据；若 \\(g\\) 降到 16，这项涨到 1 bit，「4 bit」实际占 5 bit，带宽红利被 scale 吃掉近两成。</span></p><p><span class="marginnote">「逐 token」激活量化是另一维粒度，服务上 KV 与激活常 per-token 尺度。本课主线先盯权重；激活粒度在校准课会碰头。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>权重 PTQ：从 per-channel 起，4-bit 不够再降到 group。GPTQ / AWQ 的公开实现把 group size 当检查点字段，换 \\(g\\) 必须重跑量化，不能只改推理配置。lm_head、embed 常留更高精度或更细粒度，因为误差直接进 logits。</p><p>激活：per-tensor 几乎只在无离群时能 W8A8；SmoothQuant 把难度推到权重通道尺度上，使激活能 per-tensor 或粗粒度。否则 per-channel / per-token。</p>',11)),(t(),o(p,null,{default:r(()=>[s(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22per-tensor%22%5D%20--%3E%20CHEAP%5B%22%E6%A0%B8%E7%AE%80%E5%8D%95%2C%20%E7%A6%BB%E7%BE%A4%E7%BB%91%E6%9E%B6%22%5D%0A%20%20C%5B%22per-channel%22%5D%20--%3E%20ROW%5B%22%E4%B8%80%E8%A1%8C%E4%B8%80%E4%B8%AA%20s%22%5D%0A%20%20G%5B%22per-group%22%5D%20--%3E%20META%5B%22%E5%85%83%E6%95%B0%E6%8D%AE%20x%201%2Fg%22%5D%0A%20%20G%20--%3E%20ERR%5B%22%E7%BB%84%E5%86%85%E4%BB%8D%E5%8F%AF%E6%9C%89%E9%92%89%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,"存储布局必须与核一致：group 沿哪一维切、是否 packed INT4，是契约。错维等于错尺度，质量崩了还以为是校准问题。",-1)),e[4]||(e[4]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：per-tensor 像用一把尺子量整间屋子的货物，最高的一件决定了所有刻度，其余全挤在低端；per-channel 是每排货一把尺；per-group 再把一排切段共用。尺子越多量得越准，但尺子本身也占地方。")],-1)),e[5]||(e[5]=a("h2",{id:"机制",tabindex:"-1"},[n("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[6]||(e[6]=a("p",null,"离群若沿通道对齐，per-channel 几乎消灭绑架；若离群在通道内部稀疏几个元素，只有细 group 或非均匀/混精能救。激活离群沿 hidden 维对齐时，权重侧 group 帮不上激活格子，要平滑或混精。粒度选择其实是在猜离群的轴——先测直方图的轴，再选 \\(g\\)。",-1)),e[7]||(e[7]=a("p",null,"GEMM 核按 tile 吃数据。group 边界与 tile 不对齐会强制边界处理，吞吐掉档。所以 \\(g\\) 常取 64/128，不只是精度美学。",-1)),(t(),o(p,null,{default:r(()=>[s(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%85%88%E6%B5%8B%E7%9B%B4%E6%96%B9%E5%9B%BE%EF%BC%9A%E7%A6%BB%E7%BE%A4%E5%9C%A8%E5%93%AA%E6%9D%A1%E8%BD%B4%22%5D%20--%3E%20PC%5B%22%E6%B2%BF%E8%BE%93%E5%87%BA%E9%80%9A%E9%81%93%E5%AF%B9%E9%BD%90%22%5D%0A%20%20H%20--%3E%20SP%5B%22%E8%97%8F%E5%9C%A8%E9%80%9A%E9%81%93%E5%86%85%E9%83%A8%E7%A8%80%E7%96%8F%E5%87%A0%E4%B8%AA%E5%85%83%E7%B4%A0%22%5D%0A%20%20H%20--%3E%20ACT%5B%22%E6%BF%80%E6%B4%BB%E6%B2%BF%20hidden%20%E7%BB%B4%E7%A6%BB%E7%BE%A4%22%5D%0A%20%20PC%20--%3E%20S1%5B%22per-channel%20%E5%8D%B3%E5%8F%AF%E6%B6%88%E7%81%AD%E7%BB%91%E6%9E%B6%22%5D%0A%20%20SP%20--%3E%20S2%5B%22%E7%BB%86%20group%20%E6%88%96%E6%B7%B7%E7%B2%BE%E6%89%8D%E6%95%91%E5%BE%97%E5%8A%A8%22%5D%0A%20%20ACT%20--%3E%20S3%5B%22%E5%B9%B3%E6%BB%91%20%2F%20per-token%EF%BC%8C%E6%9D%83%E9%87%8D%E4%BE%A7%20group%20%E6%97%A0%E6%95%88%22%5D%0A%20%20S1%20--%3E%20TILE%5B%22%E5%86%8D%E5%AF%B9%E9%BD%90%20GEMM%20tile%EF%BC%8Cg%20%E5%B8%B8%E5%8F%96%2064%2F128%22%5D%0A%20%20S2%20--%3E%20TILE%0A%20%20S3%20--%3E%20TILE%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=E('<p><span class="marginnote">双重量化（QLoRA）是把 per-group 的 \\(s\\) 再量化，专治「\\(g\\) 小导致 scale 比特反弹」。它不改变 \\(W\\) 的网格几何。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把论文的 \\(g=128\\) 当物理常数。不要在没有对应核时用 \\(g=4\\) 宣传每参数 4 bit——实际带宽按解包后算。不要对不同层用不同 \\(g\\) 却共用一个加载器。下一课校准集：这些 \\(s,z\\) 从哪些样本估出来。<span class="marginnote">常见误区：以为 group size 是推理时随便改的超参。实际上 scale 是量化时按 \\(g\\) 算好写进检查点的，换 \\(g\\) 等于换一套 \\(s\\)，必须重跑量化，改配置文件只会加载出错或悄悄用错尺度。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共享尺度的范围：张量 \\(\\lt\\) 通道 \\(\\lt\\) 组 \\(\\lt\\) 元素，精度升、元数据与核复杂度升。</li><li>离群轴决定哪一档粒度够用；先测再选 \\(g\\)。</li><li>GPTQ/AWQ 的 group size 是检查点契约。</li><li>\\(g\\) 还要对齐 GEMM tile，不只对齐误差。</li><li>出处：INT8 通道量化实践；GPTQ/AWQ 分组尺度。</li></ul>',5))])}const b=i(g,[["render",u]]);export{P as __pageData,b as default};
